<?php

declare(strict_types=1);

/**
 * SocialLoginRow — OAuth provider buttons with SimpleIcons logos.
 *
 *   echo SocialLoginRow(['providers' => Auth::getActiveProviders()]);
 *
 * Props: providers (list of key, name, color, icon, url), dividerLabel ('' hides the divider).
 * "icon" is raw SVG generated by the package, so it is printed without escaping.
 */
if (!function_exists('SocialLoginRow')) {
    function SocialLoginRow(array $props = []): string
    {
        $e = static fn (mixed $value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $providers = array_values((array) ($props['providers'] ?? []));
        $divider = $props['dividerLabel'] ?? 'Or continue with';

        if ($providers === []) {
            return '';
        }

        ob_start(); ?>
<div class="space-y-5">
  <?php if ($divider !== ''): ?>
    <div class="relative flex items-center">
      <div class="grow border-t border-slate-200"></div>
      <span class="mx-4 shrink-0 text-xs font-medium uppercase tracking-wide text-slate-400"><?= $e($divider) ?></span>
      <div class="grow border-t border-slate-200"></div>
    </div>
  <?php endif; ?>

  <div class="grid gap-3 <?= count($providers) > 1 ? 'grid-cols-2' : '' ?>">
    <?php foreach ($providers as $provider): ?>
      <?php $color = preg_match('/^#[0-9A-Fa-f]{6}$/', (string) ($provider['color'] ?? '')) === 1 ? $provider['color'] : '#111827'; ?>
      <a href="<?= $e($provider['url'] ?? '#') ?>"
         class="flex items-center justify-center gap-2.5 rounded-lg bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 shadow-sm ring-1 ring-inset ring-slate-300 transition hover:bg-slate-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600">
        <span aria-hidden="true" class="h-5 w-5 shrink-0 [&>svg]:h-full [&>svg]:w-full [&>svg]:fill-current" style="color: <?= $e($color) ?>"><?= $provider['icon'] ?? '' ?></span>
        <span><?= $e($provider['name'] ?? '') ?></span>
      </a>
    <?php endforeach; ?>
  </div>
</div>
        <?php return (string) ob_get_clean();
    }
}
